import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int L = fs.nextInt();
        int C = fs.nextInt();

        int[] prev = new int[C];
        for (int j = 0; j < C; j++) {
            prev[j] = fs.nextInt();
        }

        int M = C - 1;
        int[] heights = new int[M];
        int[] stack = new int[M + 1];
        int[] cur = new int[C];
        long ans = 0;

        for (int i = 0; i < L - 1; i++) {
            for (int j = 0; j < C; j++) {
                cur[j] = fs.nextInt();
            }

            for (int j = 0; j < M; j++) {
                if (prev[j] + cur[j + 1] <= prev[j + 1] + cur[j]) {
                    heights[j]++;
                } else {
                    heights[j] = 0;
                }
            }

            int top = 0;
            for (int j = 0; j <= M; j++) {
                int curH = (j == M) ? 0 : heights[j];
                while (top > 0 && heights[stack[top - 1]] > curH) {
                    int h = heights[stack[--top]];
                    int left = (top == 0) ? -1 : stack[top - 1];
                    int w = j - left - 1;
                    if (h > 0) {
                        long area = (long) (h + 1) * (w + 1);
                        if (area > ans) ans = area;
                    }
                }
                if (j < M) {
                    stack[top++] = j;
                }
            }

            int[] temp = prev;
            prev = cur;
            cur = temp;
        }

        System.out.println(ans);
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
